css:
.loader {
  position: relative;
  width: 44px;
  height: 52px;
  transform-origin: center bottom;
  animation: sway 1.8s ease-in-out infinite;
}
.loader::before {
  content: "";
  position: absolute;
  top: 2px;
  left: 50%;
  width: 24px;
  height: 24px;
  margin-left: -12px;
  border-radius: 4px;
  background: #6366f1;
  transform: rotate(45deg);
}
.loader i {
  position: absolute;
  top: 26px;
  left: 50%;
  width: 2px;
  height: 24px;
  margin-left: -1px;
  background: #c7d2fe;
}
.loader i::before {
  content: "";
  position: absolute;
  top: 6px;
  left: -4px;
  width: 10px;
  height: 5px;
  border-radius: 50%;
  background: #4338ca;
}
.loader i::after {
  content: "";
  position: absolute;
  top: 15px;
  left: -4px;
  width: 10px;
  height: 5px;
  border-radius: 50%;
  background: #4338ca;
}
@keyframes sway {
  0%, 100% { transform: rotate(-8deg) translateY(0); }
  50% { transform: rotate(8deg) translateY(-4px); }
}
